func maxArea(height []int) int {
    l, r := 0, len(height)-1
    best := 0
    for l < r {
        h := min(height[l], height[r])
        area := h * (r - l)
        if area > best {
            best = area
        }
        // 移动较矮侧，等高时移动哪边都行
        if height[l] < height[r] {
            l++
        } else {
            r--
        }
    }
    return best
}
